## The idea

The handed-over class has **three bugs**. (1) It reads `_wall[nr, nc]` **before** checking the bounds, so a start on the edge crashes. (2) It marks a cell visited when it is **dequeued**, so the same cell is queued many times — still the right answer, but on an open grid the queue explodes. (3) The constructor accepts **empty or ragged** input and crashes later. Fix: check bounds first, mark visited when **enqueuing**, validate input. Then extend it: IsWellFormed checks the outer wall, and Generate carves a maze with a randomised depth-first search, which always connects every open cell — so a path always exists.

## Step by step

1. Constructor: throw ArgumentException for null/empty input, rows of different lengths, or a missing S or E.
2. ShortestPath (BFS): dist[,] filled with −1; dist[start] = 0; enqueue start. Pop a cell; if it is End return its distance. For each of the 4 neighbours: skip if out of bounds (check this FIRST), a wall, or already seen; else set its distance and enqueue it.
3. IsWellFormed: at least 3×3, S ≠ E, every border cell is a wall except S and E, and S and E are not walls.
4. Generate(rows, cols, seed): require odd sizes ≥ 5. Fill with walls. Open (1,1) and push it on a stack.
5. Loop: look at the cell on top of the stack. List the neighbours two steps away that are inside the border and still walls. None → pop. Otherwise pick one at random, open the wall between and the cell itself, push it.
6. Put S at (1,1) and E at (rows−2, cols−2), and build the strings.

## Worked example

**Input:** "S.E" — one row, S on the edge

| Step | What happens |
|---|---|
| old code: dequeue S (0,0) | neighbour (1,0): reads _wall[1,0] before the bounds check → IndexOutOfRangeException |
| fixed: dequeue S, dist 0 | (1,0) and (−1,0), (0,−1) are out of bounds → skipped; (0,1) open → dist 1 |
| dequeue (0,1) | (0,2) is E, not seen → dist 2 |
| dequeue (0,2) | it is End → return 2 |

**Result:** 2 — and no crash

## Cost

ShortestPath is O(rows × cols) time and memory: each cell is queued at most once (that is what marking on enqueue guarantees). Generate is O(rows × cols); it uses an explicit stack, so a big maze cannot overflow the call stack.

## The code (C#, compiled and tested against every part of the question)

```csharp
public sealed class Maze {
    private readonly bool[,] _wall;                    // true = wall
    public int Rows { get; }
    public int Cols { get; }
    public (int R, int C) Start { get; }
    public (int R, int C) End { get; }

    public Maze(string[] rows) {
        // Bug 3: empty or ragged input used to crash later. Reject it here.
        if (rows == null || rows.Length == 0) throw new ArgumentException("maze is empty");
        Rows = rows.Length;
        Cols = rows[0].Length;
        if (Cols == 0) throw new ArgumentException("maze is empty");
        for (int r = 0; r < Rows; r++) {
            if (rows[r] == null || rows[r].Length != Cols) throw new ArgumentException("rows have different lengths");
        }

        _wall = new bool[Rows, Cols];
        bool foundStart = false;
        bool foundEnd = false;
        for (int r = 0; r < Rows; r++) {
            for (int c = 0; c < Cols; c++) {
                char ch = rows[r][c];
                _wall[r, c] = ch == '#';
                if (ch == 'S') { Start = (r, c); foundStart = true; }
                if (ch == 'E') { End = (r, c); foundEnd = true; }
            }
        }
        if (!foundStart || !foundEnd) throw new ArgumentException("maze needs an S and an E");
    }

    public bool IsWall(int r, int c) {
        return _wall[r, c];
    }

    // Fewest steps from S to E moving up/down/left/right; -1 if there is no path.
    public int ShortestPath() {
        var dist = new int[Rows, Cols];
        for (int r = 0; r < Rows; r++)
            for (int c = 0; c < Cols; c++)
                dist[r, c] = -1;                       // -1 = not seen yet

        int[] dRow = { 1, -1, 0, 0 };
        int[] dCol = { 0, 0, 1, -1 };

        var queue = new Queue<(int R, int C)>();
        dist[Start.R, Start.C] = 0;
        queue.Enqueue(Start);

        while (queue.Count > 0) {
            var cell = queue.Dequeue();
            if (cell == End) return dist[cell.R, cell.C];

            for (int k = 0; k < 4; k++) {
                int nr = cell.R + dRow[k];
                int nc = cell.C + dCol[k];
                // Bug 1: check the bounds BEFORE reading _wall[nr, nc].
                if (nr < 0 || nc < 0 || nr >= Rows || nc >= Cols) continue;
                if (_wall[nr, nc]) continue;
                if (dist[nr, nc] >= 0) continue;       // already queued
                // Bug 2: mark it when it is QUEUED, so it can never be queued twice.
                dist[nr, nc] = dist[cell.R, cell.C] + 1;
                queue.Enqueue((nr, nc));
            }
        }
        return -1;
    }

    // Closed outer wall (except S and E), at least 3x3, S and E open and different.
    public bool IsWellFormed() {
        if (Rows < 3 || Cols < 3) return false;
        if (Start == End) return false;
        for (int r = 0; r < Rows; r++) {
            for (int c = 0; c < Cols; c++) {
                bool onBorder = r == 0 || c == 0 || r == Rows - 1 || c == Cols - 1;
                bool isOpening = (r, c) == Start || (r, c) == End;
                if (onBorder && !isOpening && !_wall[r, c]) return false;   // a hole in the wall
            }
        }
        return !_wall[Start.R, Start.C] && !_wall[End.R, End.C];
    }

    // A maze that always has a path: randomised depth-first carving connects every open cell.
    public static Maze Generate(int rows, int cols, int seed) {
        if (rows < 5 || cols < 5 || rows % 2 == 0 || cols % 2 == 0)
            throw new ArgumentException("use odd dimensions of at least 5");

        var grid = new char[rows, cols];
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
                grid[r, c] = '#';

        var random = new Random(seed);
        int[] dRow = { 2, -2, 0, 0 };                  // jump two cells: the one between is a wall
        int[] dCol = { 0, 0, 2, -2 };

        var stack = new Stack<(int R, int C)>();
        grid[1, 1] = '.';
        stack.Push((1, 1));

        while (stack.Count > 0) {
            var cell = stack.Peek();

            // Neighbours two steps away that are inside the border and not carved yet.
            var options = new List<int>();
            for (int k = 0; k < 4; k++) {
                int nr = cell.R + dRow[k];
                int nc = cell.C + dCol[k];
                if (nr > 0 && nc > 0 && nr < rows - 1 && nc < cols - 1 && grid[nr, nc] == '#') options.Add(k);
            }

            if (options.Count == 0) {
                stack.Pop();                           // dead end: go back
                continue;
            }

            int pick = options[random.Next(options.Count)];
            int wallR = cell.R + dRow[pick] / 2;
            int wallC = cell.C + dCol[pick] / 2;
            int nextR = cell.R + dRow[pick];
            int nextC = cell.C + dCol[pick];
            grid[wallR, wallC] = '.';                  // knock down the wall between
            grid[nextR, nextC] = '.';
            stack.Push((nextR, nextC));
        }

        grid[1, 1] = 'S';
        grid[rows - 2, cols - 2] = 'E';

        var lines = new string[rows];
        for (int r = 0; r < rows; r++) {
            var row = new char[cols];
            for (int c = 0; c < cols; c++) row[c] = grid[r, c];
            lines[r] = new string(row);
        }
        return new Maze(lines);
    }
}
```

## Likely follow-up questions

**Q: Empty, ragged, no S or E, S equals E?**

Constructor validation; IsWellFormed rules

**Q: BFS cost? Generation cost?**

O(cells) each

**Q: Very large maze?**

Iterative generation; memory O(cells)

**Q: Many path queries at once.**

Immutable after construction → no locks

**Q: A 10,000 × 10,000 maze.**

Bit-packed walls; bidirectional BFS

**Q: A user reports a broken maze.**

Seeded generation reproduces it

