T.Eq("S on the edge", new Maze(new[] { "S.E" }).ShortestPath(), 2);
var m = new Maze(new[] { "#S#####", "#...#.#", "#.#.#.#", "#.#...#", "#####E#" });
T.Eq("shortest path", m.ShortestPath(), 8);
T.Eq("no path", new Maze(new[] { "#S###", "#.#.#", "###.#", "#..E#", "#####" }).ShortestPath(), -1);
T.Throws<ArgumentException>("ragged grid rejected", () => new Maze(new[] { "S..", "E" }));
T.Throws<ArgumentException>("empty grid rejected", () => new Maze(new string[0]));

bool ok = true;
for (int seed = 0; seed < 200; seed++) {
    var g = Maze.Generate(21, 31, seed);
    if (!g.IsWellFormed() || g.ShortestPath() < 0) ok = false;
}
T.True("200 generated mazes: well formed and solvable", ok);
T.Eq("same seed, same maze", Maze.Generate(11, 11, 5).ShortestPath(), Maze.Generate(11, 11, 5).ShortestPath());
T.Throws<ArgumentException>("even dimensions rejected", () => Maze.Generate(10, 11, 1));
